--初始化活动信息
function TalentQuestComponent:InitActiveInfo(jsonData)
    if not jsonData then 
        return
    end

    self._activeUuid = checkNumber(jsonData.activityUuid)
    self._activeCloseTime = checkNumber(jsonData.closeTime)

    self:StartTimeDown()
end

--入口
function TalentQuestComponent:TalentQuestHomeReq(cb)
    GameUtils.Request(Interfaces.TalentQuestHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        
        self._ticketsNum = checkNumber(jsonData.tickets)            
        self._ticketsRecoverTime = checkNumber(jsonData.ticketsRecoverTime)              
        self._buyTicketsTimes = checkNumber(jsonData.buyTicketsTimes)                 
        self._remainingTime = checkNumber(jsonData.cycleTimeLeft)                  
        self._curPlanId = checkNumber(jsonData.cycleId)                       
        self._difficultyMax = checkNumber(jsonData.level)                   
        self._lastTalentRewards = jsonData.lastTalentRewards           
        self._cardsInfo = checkTable(jsonData.cardsInfo)    

        local chapterInfo = jsonData.chapterInfo
        self._curCopyId = checkNumber(chapterInfo.currentChapterId)                     
        self._curQuestId = checkNumber(chapterInfo.questId)            
        self._buffIds = checkTable(chapterInfo.buffInfo)       
        self._curNeedChooseBuff = checkTable(chapterInfo.currentQuestBuff)       
        self._isActivity = checkNumber(chapterInfo.isActivity)      

        if cb then
            cb()
        end
    end)
end

function TalentQuestComponent:StartTimeDown()
    self:ClearTimeDown()
    local maxNum = QuestConfMgr:GetInstance():GetTalentMaxTicketHave()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self._ticketsNum < maxNum then
            self._ticketsRecoverTime = self._ticketsRecoverTime - 1
            if self._ticketsRecoverTime == 0 then
                self._ticketsNum = self._ticketsNum + 1
                Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)
            elseif self._ticketsRecoverTime < 0 then
                self._ticketsRecoverTime = QuestConfMgr:GetInstance():GetTalentTicketRecoverTime()
            end
        else
            self._ticketsRecoverTime = 0
        end
        self._remainingTime = self._remainingTime - 1
        self._activeCloseTime = self._activeCloseTime - 1
    end, CountDownTime, false, true)
end

function TalentQuestComponent:GetActiveCloseTime()
    return checkNumber(self._activeCloseTime)
end

function TalentQuestComponent:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

---EnterCopyReq 进入一个副本
---@param copyId string 副本id
function TalentQuestComponent:EnterCopyReq(copyId, cb)
    if self:IsTimeClose() then
        GameUtils.Toast(localize("本赛季已结束"))
        return
    end

    if self:IsHasChallengeCopy() then
        return
    end
    if self._ticketsNum < 1 then
        GameUtils.Toast(localize("门票不足"))
        return
    end
    GameUtils.Request(Interfaces.TalentQuestEnterChapter, {chapterId = copyId, activityUuid = self._activeUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._curNeedChooseBuff = checkTable(jsonData.currentQuestBuff)       
        self._isActivity = checkNumber(jsonData.isActivity)
        self._ticketsNum = self._ticketsNum - 1
        Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)

        self._curCopyId = copyId
        self._curQuestId = 0
        self._buffIds = {} 
        self._cardsInfo = {}

        if cb then
            cb()
        end
    end)
end

---ChooseBuffIdReq 选择一个buff
---@param questId string 关卡id
---@param buffId string buffid
function TalentQuestComponent:ChooseBuffIdReq(questId, buffId, cb, errCb)
    if self:IsTimeClose() then
        GameUtils.Toast(localize("本赛季已结束"))
        if errCb then
            errCb()
        end
        return
    end
    if checkNumber(questId) == 0 then
        if errCb then
            errCb()
        end
        return
    end
    
    if not self._buffIds then
        self._buffIds = {}
    end

    GameUtils.Request(Interfaces.TalentQuestSetBuff, {questId = questId, buffId = buffId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._buffIds[checkString(questId)] = buffId
    
        if cb then 
            cb()
        end
    end)
end

---DrawRewardReq 领取奖励
function TalentQuestComponent:DrawRewardReq(cb)
    if not self:IsHasChallengeCopy() then
        return
    end

    GameUtils.Request(Interfaces.TalentQuestReward, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        if rewards and table.count(rewards) > 0 then
            CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = rewards}})
            GoodsUtils.DrawRewards(rewards)
        end

        local isRedPoint = false
        local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curCopyId)
        if t then
            --通关这一个副本了
            if checkNumber(t[#t]) == checkNumber(self._curQuestId) then
                local vo = QuestConfMgr:GetInstance():GetTalentCopyVo(self._curCopyId)
                if vo then
                    --刷新挑战难度
                    if checkNumber(vo.regionLevel) > checkNumber(self._difficultyMax) then
                        self._difficultyMax = checkNumber(vo.regionLevel)

                        local allCopy = QuestConfMgr:GetInstance():GetTalentCopyIdsByPlanId(self._curPlanId)
                        isRedPoint = (self._difficultyMax <= table.count(allCopy))
                    end
                end
            end
        end

        self._curCopyId = 0
        self._curQuestId = 0
        self._buffIds = {} 
        self._curNeedChooseBuff = nil
        self._isActivity = false
        --local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
        --teamComponent:ClearTeamBySystemId(Constants.SystemToggleIds.Id22)

        Events.Broadcast(Constants.EventNames.RefreshTalentDialog, nil)
        if cb then
            cb(isRedPoint)
        end
    end)
end

---BuyTicketsReq 购买门票
function TalentQuestComponent:BuyTicketsReq()
    if self:IsTimeClose() then
        GameUtils.Toast(localize("本赛季已结束"))
        return
    end
    if self._buyTicketsTimes >= QuestConfMgr:GetInstance():GetTalentTicketMaxBuy() then
        GameUtils.Toast(localize("购买次数不足"))
        return
    elseif self._ticketsNum >= QuestConfMgr:GetInstance():GetTalentMaxTicketHave() then
        GameUtils.Toast(localize("门票已达上限"))
        return
    end
    
    local consumeId = checkNumber(QuestConfMgr:GetInstance():GetTalentTicketConsumeId())
    local consumeNum = checkNumber(QuestConfMgr:GetInstance():GetTalentTicketConsumeNum())
    if GoodsUtils.GetThingNo(consumeId) < consumeNum then
        GameUtils.Toast(localize("货币不足"))
        return
    end

    GameUtils.Request(Interfaces.TalentQuestBuyTickets, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._buyTicketsTimes = self._buyTicketsTimes + 1
        self._ticketsNum = self._ticketsNum + 1
        GoodsUtils.DrawRewards({ [1] = { goodsId = consumeId, num = -consumeNum} })

        Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)
        GameUtils.Toast(localize("购买成功"))
    end)
end

function TalentQuestComponent:UpdateQuestInfo(questId, cardInfo)
    if checkNumber(self._curCopyId) == 0 then
        return 
    end
    self._lastQuestId = questId
    self._curQuestId = questId
end

--上次通关的id
function TalentQuestComponent:GetLastQuestId()
    local id = checkNumber(self._lastQuestId)
    self._lastQuestId = 0
    return id
end

--获取装备副本的卡牌血量信息
function TalentQuestComponent:GetCardHpEngyData(cardId)
    if not self._cardsInfo then
        return nil
    end

    for k, v in pairs(self._cardsInfo) do
        if checkNumber(k) == checkNumber(cardId) then
            return v
        end
    end

    --如果没有这个card就是默认状态，满血0能量
    local data = {
        hpPercent = 1,
        energy = 0,
    }
    return data
end

--获取当前奖励产出
function TalentQuestComponent:GetCurCopyRewardOutPut(isFinal)
    if checkNumber(self._curCopyId) == 0 then
        return 0
    end
    local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curCopyId)
    if not t then
        return 0
    end

    local questId = QuestConfMgr:GetInstance():GetTalentCurChallengeQuestId()   
    local num = 0
    for k, v in pairs(t) do
        if self:IsPassQuestById(v) then
            num = QuestConfMgr:GetInstance():GetTalentRewardOutPutByQuestId(self._curCopyId, v, isFinal)
        else
            --如果是当前正在挑战的关卡 奖励比例添加
            if checkNumber(questId) == checkNumber(v) then
                num = QuestConfMgr:GetInstance():GetTalentRewardOutPutByQuestId(self._curCopyId, v, isFinal)
            end
        end
    end
    return num
end

