    local buffIds = self:GetCurBuffIds()
    if checkNumber(questId) == 0 then
        return nil
    elseif not buffIds then
        return nil
    end
    
    --[[
    local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId()
    if not t then
        return nil
    end

    local ind = table.keyof(t, checkString(questId))
    if not ind then
        return nil
    end
    ]]
    return buffIds[checkString(questId)]
end

