---IsUnlockCopy 是否解锁副本 
---@param copyId string 副本id
function TalentQuestComponent:IsUnlockCopy(copyId)
    local vo = QuestConfMgr:GetInstance():GetTalentCopyVo(copyId)
    if not vo then
        return false
    end
    local isUnlock = checkNumber(self._difficultyMax) >= checkNumber(vo.unlockNum)
    local str = isUnlock and "" or localize("通关课程_name_解锁", {_name_ = vo.unlockNum})
    return isUnlock, str
end

---IsPassQuestById 是否通关关卡
---@param questId string 关卡id
function TalentQuestComponent:IsPassQuestById(questId)
    return self:GetCurQuestId() >= checkNumber(questId)
end

--是否已经关闭
function TalentQuestComponent:IsTimeClose()
    return self._remainingTime <= 0 
 end

return TalentQuestComponent